function validate(input) {
  const [{ TeamPoints = [], PointsChange = [] }] = input;
  const teams = new Set(), names = new Set(), changed = new Set();
  for (const [id, name, points] of TeamPoints) {
    if (id === null || name === null || points === null) return 'TeamPoints rows need a team_id, a name and points.';
    if (teams.has(id)) return `team_id ${id} appears twice in TeamPoints.`;
    const key = String(name).toLowerCase();
    if (names.has(key)) return `The name ${name} appears twice.`;
    teams.add(id); names.add(key);
  }
  for (const [id, change] of PointsChange) {
    if (id === null || change === null) return 'PointsChange rows need a team_id and a points_change.';
    if (changed.has(id)) return `team_id ${id} appears twice in PointsChange.`;
    if (!teams.has(id)) return `PointsChange names team ${id}, which is not in TeamPoints.`;
    changed.add(id);
  }
  if (changed.size !== teams.size) return 'Every team needs a row in PointsChange.';
  return null;
}

generator:
function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const shuffle = list => { for (let i = list.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [list[i], list[j]] = [list[j], list[i]]; } return list; };
  const TeamPoints = [], PointsChange = [];
  if (size === 'small') {
    const countries = shuffle(['Algeria', 'Senegal', 'New Zealand', 'Croatia', 'Brazil', 'Japan', 'Morocco', 'Peru', 'Ghana', 'Spain']);
    const ids = shuffle(Array.from({ length: 12 }, (_, i) => i + 1));
    const count = Math.floor(rand() * 9);
    // A narrow points pool and small changes make old and new ties common.
    for (let i = 0; i < count; i++) TeamPoints.push([ids[i], countries[i], pick([1400, 1410, 1420, 1430, 1430, 1450])]);
    for (const [id] of shuffle(TeamPoints.slice())) PointsChange.push([id, pick([-30, -20, -10, 0, 0, 10, 20, 30])]);
  } else {
    const count = 1500;
    const ids = shuffle(Array.from({ length: count }, (_, i) => i + 1));
    const codes = shuffle(Array.from({ length: count }, (_, i) => `Team ${String.fromCharCode(65 + (i % 26))}${String(i).padStart(4, '0')}`));
    for (let i = 0; i < count; i++) TeamPoints.push([ids[i], codes[i], 1000 + Math.floor(rand() * 120)]);
    for (const [id] of shuffle(TeamPoints.slice())) PointsChange.push([id, Math.floor(rand() * 41) - 20]);
  }
  return [{ TeamPoints, PointsChange }];
}
